static ByteBuffer buildMsg(int state, long leader, long zxid, long electionEpoch, long epoch) {
    byte[] requestBytes = new byte[40];
    ByteBuffer requestBuffer = ByteBuffer.wrap(requestBytes);

    /*
     * Building notification packet to send, this is called directly only in tests
     */

    requestBuffer.clear();
    requestBuffer.putInt(state);
    requestBuffer.putLong(leader);
    requestBuffer.putLong(zxid);
    requestBuffer.putLong(electionEpoch);
    requestBuffer.putLong(epoch);
    requestBuffer.putInt(0x1);

    return requestBuffer;
}

static ByteBuffer buildMsg(int state, long leader, long zxid, long electionEpoch, long epoch, byte[] configData) {
    byte[] requestBytes = new byte[44 + configData.length];
    ByteBuffer requestBuffer = ByteBuffer.wrap(requestBytes);

    /*
     * Building notification packet to send
     */

    requestBuffer.clear();
    requestBuffer.putInt(state);
    requestBuffer.putLong(leader);
    requestBuffer.putLong(zxid);
    requestBuffer.putLong(electionEpoch);
    requestBuffer.putLong(epoch);
    requestBuffer.putInt(Notification.CURRENTVERSION);
    requestBuffer.putInt(configData.length);
    requestBuffer.put(configData);

    return requestBuffer;
}

/**
 * Constructor of FastLeaderElection. It takes two parameters, one
 * is the QuorumPeer object that instantiated this object, and the other
 * is the connection manager. Such an object should be created only once
 * by each peer during an instance of the ZooKeeper service.
 *
 * @param self  QuorumPeer that created this object
 * @param manager   Connection manager
 */
public FastLeaderElection(QuorumPeer self, QuorumCnxManager manager) {
    this.stop = false;
    this.manager = manager;
    starter(self, manager);
}

/**
 * This method is invoked by the constructor. Because it is a
 * part of the starting procedure of the object that must be on
 * any constructor of this class, it is probably best to keep as
 * a separate method. As we have a single constructor currently,
 * it is not strictly necessary to have it separate.
 *
 * @param self      QuorumPeer that created this object
 * @param manager   Connection manager
 */
private void starter(QuorumPeer self, QuorumCnxManager manager) {
    this.self = self;
    proposedLeader = -1;
    proposedZxid = -1;

    sendqueue = new LinkedBlockingQueue<>();
    recvqueue = new LinkedBlockingQueue<>();
    this.messenger = new Messenger(manager);
}

/**
 * This method starts the sender and receiver threads.
 */
public void start() {
    this.messenger.start();
}

private void leaveInstance(Vote v) {
    LOG.debug(
        "About to leave FLE instance: leader={}, zxid=0x{}, my id={}, my state={}",
        v.getId(),
        Long.toHexString(v.getZxid()),
        self.getMyId(),
        self.getPeerState());
    recvqueue.clear();
}

public QuorumCnxManager getCnxManager() {
    return manager;
}

volatile boolean stop;
public void shutdown() {
    stop = true;
    proposedLeader = -1;
    proposedZxid = -1;
    leadingVoteSet = null;
    LOG.debug("Shutting down connection manager");
    manager.halt();
    LOG.debug("Shutting down messenger");
    messenger.halt();
    LOG.debug("FLE is down");
}

/**
 * Send notifications to all peers upon a change in our vote
 */
private void sendNotifications() {
    for (long sid : self.getCurrentAndNextConfigVoters()) {
        QuorumVerifier qv = self.getQuorumVerifier();
        ToSend notmsg = new ToSend(
            ToSend.mType.notification,
            proposedLeader,
            proposedZxid,
            logicalclock.get(),
            QuorumPeer.ServerState.LOOKING,
            sid,
            proposedEpoch,
            qv.toString().getBytes(UTF_8));

        LOG.debug(
            "Sending Notification: {} (n.leader), 0x{} (n.zxid), 0x{} (n.peerEpoch), 0x{} (n.round), {} (recipient),"
                + " {} (myid) ",
            proposedLeader,
            Long.toHexString(proposedZxid),
            Long.toHexString(proposedEpoch),
            Long.toHexString(logicalclock.get()),
            sid,
            self.getMyId());

        sendqueue.offer(notmsg);
    }
}

/**
 * Check if a pair (server id, zxid) succeeds our
 * current vote.
 *
 */
protected boolean totalOrderPredicate(long newId, long newZxid, long newEpoch, long curId, long curZxid, long curEpoch) {
    LOG.debug(
        "id: {}, proposed id: {}, zxid: 0x{}, proposed zxid: 0x{}, epoch: 0x{}, proposed epoch: 0x{}",
        newId,
        curId,
        Long.toHexString(newZxid),
        Long.toHexString(curZxid),
        Long.toHexString(newEpoch),
        Long.toHexString(curEpoch));
    if (self.getQuorumVerifier().getWeight(newId) == 0) {
        return false;
    }

    /*
     * We return true if one of the following three cases hold:
     * 1- New epoch is higher
     * 2- New epoch is the same as current epoch, but new zxid is higher
     * 3- New epoch is the same as current epoch, new zxid is the same
     *  as current zxid, but server id is higher.
     */

    return ((newEpoch > curEpoch)
            || ((newEpoch == curEpoch)
                && ((newZxid > curZxid)
                    || ((newZxid == curZxid)
                        && (newId > curId)))));
}

