public boolean isForceSync() {
    return forceSync;
}

/**
 * a class that keeps track of the position
 * in the input stream. The position points to offset
 * that has been consumed by the applications. It can
 * wrap buffered input streams to provide the right offset
 * for the application.
 */
static class PositionInputStream extends FilterInputStream {

    long position;
    protected PositionInputStream(InputStream in) {
        super(in);
        position = 0;
    }

    @Override
    public int read() throws IOException {
        int rc = super.read();
        if (rc > -1) {
            position++;
        }
        return rc;
    }

    public int read(byte[] b) throws IOException {
        int rc = super.read(b);
        if (rc > 0) {
            position += rc;
        }
        return rc;
    }

    @Override
    public int read(byte[] b, int off, int len) throws IOException {
        int rc = super.read(b, off, len);
        if (rc > 0) {
            position += rc;
        }
        return rc;
    }

    @Override
    public long skip(long n) throws IOException {
        long rc = super.skip(n);
        if (rc > 0) {
            position += rc;
        }
        return rc;
    }
    public long getPosition() {
        return position;
    }

    @Override
    public boolean markSupported() {
        return false;
    }

    @Override
    public void mark(int readLimit) {
        throw new UnsupportedOperationException("mark");
    }

    @Override
    public void reset() {
        throw new UnsupportedOperationException("reset");
    }

}

/**
 * this class implements the txnlog iterator interface
 * which is used for reading the transaction logs
 */
public static class FileTxnIterator implements TxnLog.TxnIterator {

    File logDir;
    long zxid;
    TxnHeader hdr;
    Record record;
    TxnDigest digest;
    File logFile;
    InputArchive ia;
    static final String CRC_ERROR = "CRC check failed";

    PositionInputStream inputStream = null;
    //stored files is the list of files greater than
    //the zxid we are looking for.
    private ArrayList<File> storedFiles;

    /**
     * create an iterator over a transaction database directory
     * @param logDir the transaction database directory
     * @param zxid the zxid to start reading from
     * @param fastForward   true if the iterator should be fast forwarded to
     *        point to the txn of a given zxid, else the iterator will
     *        point to the starting txn of a txnlog that may contain txn of
     *        a given zxid
     * @throws IOException
     */
    public FileTxnIterator(File logDir, long zxid, boolean fastForward) throws IOException {
        this.logDir = logDir;
        this.zxid = zxid;
        init();

        if (fastForward && hdr != null) {
            while (hdr.getZxid() < zxid) {
                if (!next()) {
                    break;
                }
            }
        }
    }

    /**
     * create an iterator over a transaction database directory
     * @param logDir the transaction database directory
     * @param zxid the zxid to start reading from
     * @throws IOException
     */
    public FileTxnIterator(File logDir, long zxid) throws IOException {
        this(logDir, zxid, true);
    }

    /**
     * initialize to the zxid specified
     * this is inclusive of the zxid
     * @throws IOException
     */
    void init() throws IOException {
        storedFiles = new ArrayList<>();
        List<File> files = Util.sortDataDir(
            FileTxnLog.getLogFiles(logDir.listFiles(), 0),
            LOG_FILE_PREFIX,
            false);
        for (File f : files) {
            if (Util.getZxidFromName(f.getName(), LOG_FILE_PREFIX) >= zxid) {
                storedFiles.add(f);
            } else if (Util.getZxidFromName(f.getName(), LOG_FILE_PREFIX) < zxid) {
                // add the last logfile that is less than the zxid
                storedFiles.add(f);
                break;
            }
        }
        goToNextLog();
        next();
    }

    /**
     * Return total storage size of txnlog that will return by this iterator.
     */
    public long getStorageSize() {
        long sum = 0;
        for (File f : storedFiles) {
            sum += f.length();
        }
        return sum;
    }

    /**
     * go to the next logfile
     *
     * @return true if there is one and false if there is no
     * new file to be read
     */
    private boolean goToNextLog() throws IOException {
        if (!storedFiles.isEmpty()) {
            this.logFile = storedFiles.remove(storedFiles.size() - 1);
            try {
                ia = createInputArchive(this.logFile);
            } catch (EOFException ex) {
                // If this file is the last log file in the database and is empty,
                // it means that the last time the file was created
                // before the header was written.
                if (storedFiles.isEmpty() && this.logFile.length() == 0) {
                    boolean deleted = this.logFile.delete();
                    if (!deleted) {
                        throw new IOException("Failed to delete empty tail log file: " + this.logFile.getName());
                    }
                    LOG.warn("Delete empty tail log file to recover from corruption file: {}", this.logFile.getName());
                    return false;
                }
                throw ex;
            }
            return true;
        }
        return false;
    }

    /**
     * read the header from the inputarchive
     * @param ia the inputarchive to be read from
     * @param is the inputstream
     * @throws IOException
     */
    protected void inStreamCreated(InputArchive ia, InputStream is) throws IOException {
        FileHeader header = new FileHeader();
        header.deserialize(ia, "fileheader");
        if (header.getMagic() != FileTxnLog.TXNLOG_MAGIC) {
            throw new IOException("Transaction log: " + this.logFile
                                  + " has invalid magic number "
                                  + header.getMagic() + " != " + FileTxnLog.TXNLOG_MAGIC);
        }
    }

    /**
     * Invoked to indicate that the input stream has been created.
     * @param logFile the file to read.
     * @throws IOException
     **/
    protected InputArchive createInputArchive(File logFile) throws IOException {

        protected InputArchive createInputArchive(File logFile) throws IOException {
            if (inputStream == null) {
                inputStream = new PositionInputStream(new BufferedInputStream(new FileInputStream(logFile)));
                LOG.debug("Created new input stream: {}", logFile);
                ia = BinaryInputArchive.getArchive(inputStream);
                inStreamCreated(ia, inputStream);
                LOG.debug("Created new input archive: {}", logFile);
            }
            return ia;
        }

        /**
         * create a checksum algorithm
         * @return the checksum algorithm
         */
        protected Checksum makeChecksumAlgorithm() {
            return new Adler32();
        }

        /**
         * the iterator that moves to the next transaction
         * @return true if there is more transactions to be read
         * false if not.
         */
        public boolean next() throws IOException {
            if (ia == null) {
                return false;
            }
            try {
                long crcValue = ia.readLong("crcvalue");
                byte[] bytes = Util.readTxnBytes(ia);
                // Since we preallocate, we define EOF to be an
                if (bytes == null || bytes.length == 0) {
                    throw new EOFException("Failed to read " + logFile);
                }
                // EOF or corrupted record
                // validate CRC
                Checksum crc = makeChecksumAlgorithm();
                crc.update(bytes, 0, bytes.length);
                if (crcValue != crc.getValue()) {
                    throw new IOException(CRC_ERROR);
                }
                TxnLogEntry logEntry = SerializeUtils.deserializeTxn(bytes);
                hdr = logEntry.getHeader();
                record = logEntry.getTxn();
                digest = logEntry.getDigest();
            } catch (EOFException e) {
                LOG.debug("EOF exception", e);
                inputStream.close();
                inputStream = null;
                ia = null;
                hdr = null;
                // this means that the file has ended
                // we should go to the next file
                if (!goToNextLog()) {
                    return false;
                }
                // if we went to the next log file, we should call next() again
                return next();
            } catch (IOException e) {
                inputStream.close();
                throw e;
            }
            return true;
        }

        /**
         * return the current header
         * @return the current header that
         * is read
         */
        public TxnHeader getHeader() {
            return hdr;
        }

        /**
         * return the current transaction
         * @return the current transaction
         * that is read
         */
        public Record getTxn() {
            return record;
        }

        public TxnDigest getDigest() {
            return digest;
        }

        /**
         * close the iterator
         * and release the resources.
         */
        public void close() throws IOException {
            if (inputStream != null) {
                inputStream.close();
            }
        }

    }

}

