protected SyncedLearnerTracker getVoteTracker(Map<Long, Vote> votes, Vote vote) {
    SyncedLearnerTracker voteSet = new SyncedLearnerTracker();
    voteSet.addQuorumVerifier(self.getQuorumVerifier());
    if (self.getLastSeenQuorumVerifier() != null
        && self.getLastSeenQuorumVerifier().getVersion() > self.getQuorumVerifier().getVersion()) {
        voteSet.addQuorumVerifier(self.getLastSeenQuorumVerifier());
    }

    /*
     * First make the views consistent. Sometimes peers will have different
     * zxids for a server depending on timing.
     */
    for (Map.Entry<Long, Vote> entry : votes.entrySet()) {
        if (vote.equals(entry.getValue())) {
            voteSet.addAck(entry.getKey());
        }
    }

    return voteSet;
}

/**
 * In the case there is a leader elected, and a quorum supporting
 * this leader, we have to check if the leader has voted and acked
 * that it is leading. We need this check to avoid that peers keep
 * electing over and over a peer that has crashed and it is no
 * longer leading.
 *
 * @param votes set of votes
 * @param   leader  leader id
 * @param   electionEpoch   epoch id
 */
protected boolean checkLeader(Map<Long, Vote> votes, long leader, long electionEpoch) {

    boolean predicate = true;

    /*
     * If everyone else thinks I'm the leader, I must be the leader.
     * The other two checks are just for the case in which I'm not the
     * leader. If I'm not the leader and I haven't received a message
     * from leader stating that it is leading, then predicate is false.
     */

    if (leader != self.getMyId()) {
        if (votes.get(leader) == null) {
            predicate = false;
        } else if (votes.get(leader).getState() != ServerState.LEADING) {
            predicate = false;
        }
    } else if (logicalclock.get() != electionEpoch) {
        predicate = false;
    }

    return predicate;
}

synchronized void updateProposal(long leader, long zxid, long epoch) {
    LOG.debug(
        "Updating proposal: {} (newleader), 0x{} (newzxid), {} (oldleader), 0x{} (oldzxid)",
        leader,
        Long.toHexString(zxid),
        proposedLeader,
        Long.toHexString(proposedZxid));

    proposedLeader = leader;
    proposedZxid = zxid;
    proposedEpoch = epoch;
}

public synchronized Vote getVote() {
    return new Vote(proposedLeader, proposedZxid, proposedEpoch);
}

/**
 * A learning state can be either FOLLOWING or OBSERVING.
 * This method simply decides which one depending on the
 * role of the server.
 *
 * @return ServerState
 */
private ServerState learningState() {
    if (self.getLearnerType() == LearnerType.PARTICIPANT) {
        LOG.debug("I am a participant: {}", self.getMyId());
        return ServerState.FOLLOWING;
    } else {
        LOG.debug("I am an observer: {}", self.getMyId());
        return ServerState.OBSERVING;
    }
}

/**
 * Returns the initial vote value of server identifier.
 *
 * @return long
 */
private long getInitId() {
    if (self.getQuorumVerifier().getVotingMembers().containsKey(self.getMyId())) {
        return self.getMyId();
    } else {
        return Long.MIN_VALUE;
    }
}

/**
 * Returns initial last logged zxid.
 *
 * @return long
 */
private long getInitLastLoggedZxid() {
    if (self.getLearnerType() == LearnerType.PARTICIPANT) {
        return self.getLastLoggedZxid();
    } else {
        return Long.MIN_VALUE;
    }
}

/**
 * Returns the initial vote value of the peer epoch.
 *
 * @return long
 */
private long getPeerEpoch() {
    if (self.getLearnerType() == LearnerType.PARTICIPANT) {
        try {
            return self.getCurrentEpoch();
        } catch (IOException e) {
            RuntimeException re = new RuntimeException(e.getMessage());
            re.setStackTrace(e.getStackTrace());
            throw re;
        }
    } else {
        return Long.MIN_VALUE;
    }
}

